   "id": "zbd5f6833",
   "sez": "prima",
   "titolo": "Uragano Simon, la presidente messicana chiede ai residenti di mettersi al riparo",
   "orig": "Mexican president urges residents to shelter as Hurricane Simon approaches",
   "lead": "La presidenza del Messico ha invitato gli abitanti delle zone minacciate dall'uragano Simon a cercare riparo mentre la tempesta si avvicina alla costa. Il ciclone, classificato di categoria 4, si muove al largo dello Stato di Jalisco, sul versante pacifico del Paese. La comunità più esposta è quella di Cabo Corrientes, che rischia di essere colpita in pieno dall'occhio della tempesta. L'appello delle autorità punta a ridurre i rischi per la popolazione prima dell'arrivo dei venti più forti e delle piogge. Lo riferisce Al Jazeera.",
   "more": [
    "Jalisco è uno Stato del Messico occidentale affacciato sull'oceano Pacifico, noto per la località turistica di Puerto Vallarta. Gli uragani vengono classificati con la scala Saffir-Simpson, che va da 1 a 5 in base alla velocità del vento: la categoria 4 indica una tempesta capace di provocare danni gravi a edifici, alberi e reti elettriche."
   ],
