   "id": "z64ab2c9f",
   "sez": "mondo",
   "titolo": "Marianne Settentrionali, il governatore: non c'è terra per una grande base militare Usa",
   "orig": "Northern Marianas lacks land to host new major US military base, governor says",
   "lead": "Il governatore del Commonwealth delle Isole Marianne Settentrionali ha dichiarato che il territorio non dispone di terreni sufficienti per ospitare una nuova e vasta base militare degli Stati Uniti. La presa di posizione arriva mentre si discute dell'ipotesi di realizzare nell'arcipelago un importante insediamento delle forze armate americane. Secondo il governatore, la disponibilità di spazio sulle isole non basta per un progetto di tali dimensioni. Lo riferisce RNZ Pacific.",
   "more": [
    "Le Isole Marianne Settentrionali sono un territorio degli Stati Uniti nel Pacifico occidentale, vicino a Guam, con capitale Saipan. L'area ha un forte valore strategico per Washington, che negli ultimi anni ha rafforzato la propria presenza militare nella regione. Le isole sono piccole e lo spazio a disposizione è limitato."
   ],
