   "id": "z606a8005",
   "sez": "mondo",
   "titolo": "Myanmar, aziende malesi legate alla filiera dell'aviazione militare",
   "orig": "Malaysian Firms Linked to Myanmar Military Aviation Supply Chain: JFM",
   "lead": "L'organizzazione Justice For Myanmar ha individuato tre aziende aerospaziali della Malesia con legami con l'esercito del Myanmar, inserite nella catena di fornitura della sua aviazione militare. Tra queste figurano una società di proprietà statale e un'altra sostenuta da finanziamenti pubblici del governo di Kuala Lumpur. La denuncia riporta l'attenzione sui canali attraverso cui la giunta birmana continua a procurarsi mezzi e servizi per i propri aerei. Lo riferisce The Irrawaddy.",
   "more": [
    "Justice For Myanmar è un gruppo di attivisti che indaga sugli interessi economici dell'esercito birmano. Dal colpo di Stato del 2021 la giunta è accusata di bombardamenti aerei contro civili e gruppi armati di opposizione, motivo per cui le forniture all'aviazione militare sono oggetto di particolare attenzione internazionale."
   ],
