   "sez": "mondo",
   "titolo": "Giappone, il rimpasto non sposta il consenso per la premier Takaichi",
   "orig": "Approval Ratings Largely Level for Takaichi Following Limited Impact of September Cabinet Reshuffle",
   "lead": "Il rimpasto di governo del 17 settembre ha portato alla premier giapponese Sanae Takaichi qualche segnale positivo nei sondaggi, ma nel complesso il gradimento del suo esecutivo è rimasto sostanzialmente invariato. L'effetto della riorganizzazione del governo è stato quindi limitato. Secondo l'analisi, l'attenzione dell'opinione pubblica resta concentrata sull'ombra degli scandali e sulle prospettive delle future scelte politiche del governo di Tokyo. Lo riferisce Nippon.com.",
   "more": [
    "Sanae Takaichi, esponente dell'ala conservatrice del Partito liberaldemocratico, è la prima donna a guidare il governo del Giappone. Nel sistema politico giapponese i sondaggi sul gradimento del governo sono seguiti con grande attenzione, perché un calo prolungato può indebolire la posizione del primo ministro all'interno del suo stesso partito."
   ],
