   "id": "za7c5ccfc",
   "sez": "economia",
   "titolo": "Giappone, con i prezzi alti si mangia più a casa",
   "orig": "Dining In is the New Dining Out in Japan as Food Prices Continue to Rise",
   "lead": "In Giappone sempre più persone rinunciano ai pasti fuori e scelgono di mangiare a casa. Secondo un sondaggio, il 62,1% degli intervistati ha dichiarato di cenare più spesso tra le mura domestiche e di frequentare meno ristoranti e locali. Il motivo indicato più di frequente è l'aumento dei prezzi, in particolare quelli degli alimenti, che continuano a salire e spingono le famiglie a rivedere le proprie abitudini di spesa. Lo riferisce Nippon.com.",
   "more": [
    "Per decenni il Giappone ha conosciuto prezzi stabili o in calo. Negli ultimi anni, invece, l'inflazione è tornata a farsi sentire, anche per la debolezza dello yen, che rende più costose le importazioni di cibo ed energia, e per il rincaro di alimenti di base come il riso."
   ],
