   "sez": "mondo",
   "titolo": "Sudan, la campagna per la giustizia femminista chiude la prima fase",
   "orig": "Sudan Feminist Justice Campaign concludes first phase, achieves half its goals",
   "lead": "La Sudan Feminist Justice Campaign ha concluso la sua prima fase raggiungendo circa metà degli obiettivi prefissati. L'iniziativa, durata sei mesi, aveva lo scopo di mobilitare le voci femministe e di rafforzare la partecipazione delle donne sudanesi ai processi di costruzione della pace nel Paese. Il bilancio parziale indica risultati ottenuti ma anche un percorso ancora lungo per coinvolgere le donne nelle decisioni sul futuro del Sudan. Lo riferisce Dabanga.",
