   "titolo": "Bolivia, 18,6 milioni di dollari per rifare la strada Comarapa–Santa Cruz",
   "orig": "La rehabilitación del tramo Comarapa – Santa Cruz, se llevará $us 18,6 MM, de los $us 75 MM de Fonplata",
   "lead": "In Bolivia la riabilitazione del tratto stradale tra Comarapa e Santa Cruz costerà 18,6 milioni di dollari, una parte dei 75 milioni messi a disposizione dal fondo Fonplata. L'intervento riguarda la Rete viaria fondamentale del Paese, che supera i 17mila chilometri e collega i capoluoghi dei dipartimenti, le aree produttive e i valichi di frontiera. L'opera punta a migliorare i collegamenti su un asse importante per l'economia nazionale. Lo riferisce El Deber.",
   "more": [
    "Santa Cruz de la Sierra è la città più popolosa della Bolivia e il principale motore economico del Paese, grazie all'agricoltura e all'allevamento. Fonplata è un'istituzione finanziaria regionale creata dai Paesi del bacino del Río de la Plata per finanziare progetti di sviluppo e integrazione."
   ],
