   "id": "z184ab309",
   "sez": "mondo",
   "titolo": "Africa, le ragazze chiedono di fermare i matrimoni precoci",
   "orig": "Des jeunes filles du Kasaï-Oriental appellent à mettre fin aux mariages précoces",
   "lead": "Nella Giornata internazionale delle bambine, l'11 ottobre, in Africa si moltiplicano le voci contro i matrimoni precoci. Nella provincia del Kasai Orientale, nella Repubblica Democratica del Congo, alcune ragazze hanno chiesto di porre fine alle nozze delle minorenni. In Ciad, a N'Djamena, le guide dell'arcidiocesi hanno celebrato una messa di ringraziamento nella parrocchia di Saint-Paul de Kabalaye sul tema della fine dei matrimoni infantili e dell'investimento nei diritti delle ragazze.",
   "more": [
    "I matrimoni precoci, cioè le unioni che coinvolgono minori, sono diffusi in diverse aree dell'Africa subsahariana. Le organizzazioni internazionali li considerano una violazione dei diritti dell'infanzia, perché spesso interrompono gli studi delle ragazze e le espongono a gravidanze precoci e a maggiori rischi per la salute."
   ],
