   "id": "z4bb99126",
   "sez": "salute",
   "titolo": "Nhs, «segnali inquietanti» di pressione invernale con le liste d'attesa in crescita",
   "orig": "'Ominous signs' of winter pressures as NHS waiting list grows",
   "lead": "Nel servizio sanitario inglese, l'Nhs, si vedono già «segnali inquietanti» della pressione tipica dell'inverno. Le liste d'attesa si allungano e aumentano i tempi per gli interventi chirurgici programmati. L'agenzia per la sicurezza sanitaria del Regno Unito, la UKHSA, avverte che i livelli di influenza sono insolitamente alti per il periodo, superiori a quelli dei quattro anni precedenti all'inizio della stagione di monitoraggio invernale, mentre anche il covid contribuisce al carico sugli ospedali.",
   "more": [
    "L'Nhs è il servizio sanitario pubblico britannico, gratuito al momento dell'uso. Ogni inverno gli ospedali affrontano un aumento dei ricoveri dovuto a influenza, virus respiratori e malanni stagionali, che riduce i posti letto disponibili e costringe spesso a rinviare gli interventi non urgenti."
   ],
