   "id": "z1c9df500",
   "sez": "mondo",
   "titolo": "Polonia, arrestato un uomo che preparava un attentato contro il premier Tusk",
   "orig": "Man in Polen opgepakt voor het plannen van een aanslag op premier Tusk",
   "lead": "In Polonia è stato arrestato un uomo accusato di preparare un attentato contro il primo ministro Donald Tusk. Lo ha annunciato domenica il ministro dell'Interno Marcin Kierwiński. Prima dell'arresto, i servizi di sicurezza si erano riuniti d'urgenza dopo aver ricevuto informazioni su un possibile attacco contro Tusk e il ministro della Difesa Władysław Kosiniak-Kamysz, una minaccia considerata «estremamente seria». Non sono stati resi noti l'identità del sospettato, il movente né le modalità previste. Tusk ha ringraziato la polizia per l'intervento rapido e deciso.",
   "more": [
    "Donald Tusk, leader della formazione liberale Coalizione civica, è stato presidente del Consiglio europeo ed è tornato alla guida del governo polacco dopo le elezioni del 2023. La Polonia, confinante con Ucraina, Bielorussia e l'enclave russa di Kaliningrad, è un Paese molto attento ai rischi per la sicurezza interna."
   ],
