   "titolo": "Il Memorial Bettega torna a Rallylegend, vince Dani Sordo",
   "orig": "Memorial Bettega, ritorno da Legend!",
   "lead": "Il Memorial Bettega è tornato protagonista a Rallylegend e si è disputato per la prima volta a San Marino. In passato la gara si correva al Motor Show di Bologna, dove ha vissuto i suoi anni migliori. L'edizione prevedeva quattro categorie, con sfide combattute e molto spettacolo per il pubblico. Nella categoria WRX ha vinto lo spagnolo Dani Sordo, al volante della Hyundai Rally1. Lo riferisce San Marino RTV.",
