   "sez": "sport",
   "titolo": "Rossi festeggia 100 presenze con il Tropical: «Col Pontedera non si può sbagliare»",
   "orig": "Rossi fa 100 col Tropical: \"Motivo d'orgoglio. Col Pontedera non si può sbagliare\"",
   "lead": "Il difensore della nazionale sammarinese Rossi ha raggiunto le cento presenze con la maglia del Tropical. Il giocatore lo definisce un motivo d'orgoglio. Ora guarda alla prossima sfida, mercoledì contro il Pontedera, in cui secondo lui non si può sbagliare. Rossi spiega che, con una vittoria e i tre punti, la squadra potrebbe pensare a un campionato diverso, con ambizioni più alte. Lo riferisce San Marino RTV.",
