   "id": "z363d9e4f",
   "sez": "mondo",
   "titolo": "Figi, il ministero ammette: mancavano controlli sui sussidi per la casa",
   "orig": "Housing grants lack proper monitoring",
   "lead": "Il ministero dell'Edilizia abitativa delle Figi ha riconosciuto che in passato mancavano controlli adeguati per verificare che le famiglie usassero i contributi pubblici per la casa allo scopo previsto. L'ammissione è arrivata dal segretario permanente Manasa Lesuma, che ha presentato il rapporto annuale del ministero relativo agli anni 2019-2021 davanti alla Commissione parlamentare per gli Affari sociali. Lesuma ha spiegato che da allora il ministero ha collaborato con le banche per apporre vincoli a tutela dell'uso dei fondi. Lo riferisce FBC News.",
   "more": [
    "Le Figi sono un arcipelago del Pacifico meridionale, con capitale Suva. Nei sistemi di tradizione britannica il segretario permanente è il più alto funzionario non politico di un ministero, e le commissioni parlamentari esaminano i rapporti annuali per controllare l'operato dell'amministrazione."
   ],
