   "id": "z106a4769",
   "sez": "economia",
   "titolo": "Figi, il fondo previdenziale FNPF lancia un concorso per i suoi 60 anni",
   "orig": "FNPF launches 60th anniversary competition",
   "lead": "Il Fiji National Provident Fund, il fondo previdenziale nazionale delle Figi, ha avviato un concorso per celebrare i suoi sessant'anni di attività. L'iniziativa invita gli iscritti ad aumentare i propri risparmi, offrendo loro la possibilità di vincere premi. Secondo Alipate Waqairawai, direttore generale per i servizi agli iscritti, lo scopo è spingere un numero maggiore di cittadini a sfruttare le diverse opzioni di adesione messe a disposizione dal fondo. Lo riferisce FBC News.",
   "more": [
    "I fondi previdenziali nazionali, diffusi in molti Paesi di tradizione britannica, raccolgono contributi obbligatori di lavoratori e datori di lavoro per costituire un risparmio destinato alla pensione. Spesso prevedono anche forme di adesione volontaria per chi lavora in proprio."
   ],
