   "id": "zf8285957",
   "sez": "mondo",
   "titolo": "Russia, gioielli spariti dopo la perquisizione dell'influencer Lerchek: il caso sull'investigatore",
   "orig": "Russian prosecutors cancel criminal case against investigator over missing jewelry seized from influencer Valeria Chekalina",
   "lead": "In Russia una parte dei gioielli sequestrati durante la perquisizione dell'abitazione della blogger Valeria Chekalina, nota come Lerchek, è scomparsa. Lo ha comunicato su Telegram la portavoce del ministero dell'Interno, Irina Volk. Le autorità avevano aperto un procedimento penale contro uno degli investigatori che seguivano il caso a carico dell'influencer, ma secondo il titolo la procura ha ora annullato quell'indagine. Lo riferisce Meduza.",
   "more": [
    "Valeria Chekalina è una delle influencer russe più seguite, nota con il soprannome Lerchek, ed è da tempo al centro di un procedimento giudiziario. Irina Volk è la portavoce ufficiale del ministero dell'Interno russo e usa abitualmente Telegram per le comunicazioni pubbliche."
   ],
