   "titolo": "Nigeria 2027, esclusi i candidati di ADC e NDC al governatorato di Cross River",
   "orig": "2027: ADC, NDC candidates not cleared for Cross River governorship",
   "lead": "In vista delle elezioni del 2027 in Nigeria, i candidati dei partiti ADC e NDC non sono stati ammessi alla corsa per la carica di governatore dello Stato di Cross River. Secondo quanto riportato dall'agenzia di stampa nigeriana NAN, la lista definitiva della commissione elettorale INEC prevede candidati di soli otto partiti politici per questa elezione. L'esclusione riduce così il numero di formazioni in competizione nello Stato. Lo riferisce Premium Times.",
   "more": [
    "La Nigeria è una repubblica federale composta da 36 Stati, ciascuno guidato da un governatore eletto. Cross River si trova nel sud-est del Paese, al confine con il Camerun. L'INEC è la commissione elettorale nazionale indipendente che organizza il voto."
   ],
