   "sez": "sport",
   "titolo": "Reinhard Jumamoy, il leader audace dei Bulldogs di NU",
   "orig": "Reinhard Jumamoy’s audacity, work ethic give NU its go-to guy",
   "lead": "I Bulldogs della National University, squadra di pallacanestro universitaria filippina, hanno trovato in Reinhard Jumamoy il giocatore su cui contare nei momenti decisivi. Secondo Rappler, sono soprattutto la sua audacia e la sua etica del lavoro a renderlo il riferimento della squadra. L'atleta viene descritto come il leader sfrontato di cui il gruppo aveva bisogno, capace di prendersi responsabilità in campo. Il ritratto racconta come la sua personalità abbia dato alla squadra una guida chiara nella stagione in corso, colmando un vuoto di leadership. Lo riferisce Rappler.",
   "more": [
    "La National University di Manila partecipa al campionato universitario filippino UAAP, molto seguito nel Paese. La pallacanestro è lo sport più popolare delle Filippine e i tornei universitari sono spesso un trampolino verso il professionismo."
   ],
