   "titolo": "Thailandia, respinto il ricorso del giornalista cinese ricercato da Pechino",
   "orig": "Thai court dismisses detention challenge by Chinese journalist sought by Beijing",
   "lead": "Un tribunale thailandese ha respinto venerdì il ricorso del giornalista investigativo cinese Bai Zhaodong contro la sua lunga detenzione a Bangkok. La decisione è arrivata un giorno dopo l'avvio da parte delle autorità della procedura per estradarlo in Cina, che lo ricerca, come ha riferito il suo avvocato. Bai, riconosciuto dalle Nazioni Unite come rifugiato, aveva lasciato la Cina nel 2023 ed era arrivato in Thailandia l'anno seguente. Lo riferisce Hong Kong Free Press.",
   "more": [
    "La Thailandia è stata criticata in passato da organizzazioni per i diritti umani per aver rimandato in Cina dissidenti e membri di minoranze. Lo status di rifugiato riconosciuto dall'Onu dovrebbe proteggere una persona dal rimpatrio in un Paese dove rischia persecuzioni."
   ],
