   "titolo": "A Dearborn i musulmani che votarono Trump hanno cambiato idea",
   "orig": "I musulmani che avevano votato Trump non sono più così convinti",
   "lead": "Il Post è andato a Dearborn, in Michigan, la più grande città degli Stati Uniti a maggioranza araba, per raccontare come sono cambiati gli umori degli elettori musulmani che avevano sostenuto Donald Trump. Molti di loro oggi si dicono molto meno convinti della loro scelta e affermano di non voler più farsi «ingannare». Il reportage raccoglie il malcontento di una comunità che aveva puntato sul candidato repubblicano e che ora ne prende le distanze. Lo riferisce Il Post.",
   "more": [
    "Dearborn è una città vicino a Detroit con una grande comunità di origine araba, soprattutto libanese, yemenita e irachena. Alle elezioni presidenziali parte di questi elettori, delusi dai democratici per la posizione sulla guerra a Gaza, aveva scelto Trump."
   ],
