   "titolo": "Lazio, la «porta della regione» poco nota a un'ora da Roma",
   "orig": "Lazio, la “porta della regione” a meno di un’ora dalla Capitale: tutti la snobbano, ma vale la sosta",
   "lead": "Turisti per Caso propone un itinerario in un borgo del Lazio definito la «porta della regione», a meno di un'ora di distanza da Roma. Secondo la testata, si tratta di un luogo che molti trascurano ma che merita una sosta. Il percorso suggerito attraversa grotte, vicoli e panorami poco conosciuti, descritti come il cuore nascosto dell'Italia centrale. L'articolo invita a scoprire una meta alternativa rispetto alle destinazioni più frequentate intorno alla capitale. Lo riferisce Turisti per Caso.",
