   "sez": "cultura",
   "titolo": "Il Nobel aiuta gli hibakusha a passare il testimone antinucleare",
   "orig": "Nobel Prize Helps Aging Hibakusha Pass Antinuclear Torch: An Interview with Hamasumi Jirō of Nihon Hidankyō",
   "lead": "Nippon.com ha intervistato Hamasumi Jirō, segretario generale di Nihon Hidankyō, l'organizzazione giapponese di base che riunisce i sopravvissuti alle bombe atomiche. Due anni fa il gruppo ha ricevuto il premio Nobel per la pace per la sua lunga battaglia contro le armi nucleari. Hamasumi racconta l'effetto del riconoscimento sul movimento e gli sforzi per trasmettere l'impegno a una nuova generazione di attivisti, mentre i sopravvissuti diventano sempre più anziani. Lo riferisce Nippon.com.",
   "more": [
    "Gli hibakusha sono i sopravvissuti ai bombardamenti atomici di Hiroshima e Nagasaki. Con il passare del tempo il loro numero diminuisce, e le associazioni cercano di conservarne la testimonianza affidandola ai più giovani perché il ricordo e l'appello al disarmo non si perdano."
   ],
