   "lead": "Marvel Animation ha presentato una serie di novità per il suo catalogo di animazione. Lo studio ha annunciato tre nuovi speciali dedicati a Marvel Zombies, la versione horror dell'universo Marvel in cui gli eroi diventano zombie. Sono state presentate anche le nuove stagioni delle serie animate dedicate agli X-Men e a Spider-Man. Gli annunci confermano l'impegno dell'azienda nel portare i suoi personaggi in progetti animati destinati al pubblico dello streaming. Lo riferisce Fumettologica.",
