   "titolo": "Ungheria, il ministro Tanács spera nelle dimissioni dei vertici di HUN-REN",
   "orig": "Tanács Zoltán reméli, hogy jövő héten lemond a HUN-REN elnöke és vezérigazgatója",
   "lead": "In Ungheria il ministro Zoltán Tanács ha detto di sperare che la prossima settimana si dimettano il presidente e il direttore generale di HUN-REN. Il ministro ha parlato con il programma Kontroll e ha affrontato anche un altro tema: le spese di denaro legate al programma Gondosóra. Lo riferisce Telex English.",
   "more": [
    "HUN-REN è la rete ungherese degli istituti di ricerca. È stata creata separando gli istituti scientifici dall'Accademia ungherese delle scienze. La sua gestione è stata a lungo oggetto di dibattito nel mondo accademico ungherese."
   ],
