   "titolo": "Asia centrale, nuovi limiti all'uso dell'acqua ma quote nazionali poco chiare",
   "orig": "Central Asia Agrees New Water Limits, but National Quotas Remain Unclear",
   "lead": "L'Uzbekistan e gli altri Paesi dell'Asia centrale hanno approvato nuovi limiti ai prelievi d'acqua dai bacini dell'Amu Darya e del Syr Darya. Valgono per la stagione non irrigua 2026-2027, ma non è ancora chiaro quanta acqua spetterà a ciascun Paese. L'acqua è da tempo un motivo di attrito nella regione: rilasci non coordinati hanno allagato comunità a valle e ci sono state dispute sull'accesso. Il presidente uzbeko ha chiesto di affrontare insieme acqua e clima, e di dialogare con l'Afghanistan.",
   "more": [
    "L'Amu Darya e il Syr Darya sono i due grandi fiumi dell'Asia centrale e in passato alimentavano il lago d'Aral. Lo sfruttamento eccessivo per irrigare, soprattutto il cotone, ha fatto quasi scomparire il lago."
   ],
