   "titolo": "Nepal, sospeso lo spoglio nel Nepali Congress: i candidati vogliono i dati digitali",
   "orig": "Nepali Congress vote count halted over demand to enter tallies digitally",
   "lead": "In Nepal si è fermato lo spoglio dei voti per le elezioni interne del Nepali Congress, uno dei principali partiti del Paese. A bloccarlo sono stati alcuni candidati, che chiedono di inserire nel sistema informatico i risultati di tutte le schede già scrutinate prima di riprendere il conteggio. Con questa richiesta i candidati puntano a una registrazione più trasparente e verificabile dei dati. Non è indicato quando lo spoglio potrà ripartire. Lo riferisce The Kathmandu Post.",
   "more": [
    "Il Nepali Congress è uno dei partiti più antichi e influenti del Nepal. Di orientamento socialdemocratico, ha avuto un ruolo centrale nella transizione del Paese dalla monarchia alla repubblica federale."
   ],
