   "id": "z7eb09fd7",
   "sez": "salute",
   "titolo": "Fiducia nella scienza: gli americani sopra la media, ma il dato cala nel mondo",
   "orig": "Americans trust science more than peers around the world, survey shows",
   "lead": "Un'indagine internazionale mostra che gli statunitensi si fidano della scienza più di molti altri popoli. Il rapporto con il sistema sanitario, però, è meno solido: solo il 40% degli americani dichiara molta fiducia in ospedali e cliniche del Paese, la stessa quota rilevata in Portogallo e Uruguay. The Straits Times legge i risultati in un'altra chiave. Sottolinea che la fiducia nella scienza sta calando man mano che si attenua la spinta dell'epoca Covid-19. Il dato arriva mentre tornano a diffondersi malattie che si possono prevenire.",
   "more": [
    "I sondaggi sulla fiducia nella scienza misurano quanto le persone si affidano a ricercatori, medici e istituzioni sanitarie. Durante la pandemia questo tema è diventato centrale, perché l'adesione a vaccini e misure di prevenzione dipende anche dalla credibilità di chi le raccomanda."
   ],
