   "titolo": "Giovani agricoltori portoghesi aprono un incubatore agricolo in Mozambico",
   "orig": "Young Farmers Association of Portugal establishes agricultural incubator in Mozambique",
   "lead": "L'Associazione dei giovani agricoltori del Portogallo, AJAP, ha annunciato la nascita di un incubatore agricolo nella provincia di Tete, in Mozambico. Il progetto vuole formare giovani imprenditori del settore e ridurre la dipendenza del Paese dalle importazioni alimentari. L'iniziativa nasce da una partnership tra l'associazione e altri enti. Tra gli obiettivi c'è quello di valorizzare il potenziale della valle dello Zambesi. Lo riferisce Club of Mozambique.",
   "more": [
    "La provincia di Tete si trova nel Mozambico nord-occidentale ed è attraversata dal fiume Zambesi. Il Portogallo e il Mozambico mantengono legami stretti dovuti al passato coloniale e alla lingua portoghese, che resta la lingua ufficiale del Paese africano."
   ],
