   "sez": "spazio",
   "titolo": "La NASA sceglie GIMLI per esplorare la fossa lunare di Marius in vista di una base",
   "orig": "NASA Selects GIMLI to Search the Marius Lunar Pit for a Potential Lunar Base Site",
   "lead": "La NASA ha selezionato GIMLI, una proposta guidata dal Planetary Science Institute, per studiare la fossa lunare di Marius. L'obiettivo è verificare se una caverna sotterranea, potenzialmente di grandi dimensioni, si estenda oltre l'apertura della fossa. L'indagine rientra nella ricerca di siti adatti a ospitare in futuro una possibile base lunare, che potrebbe sfruttare queste cavità naturali. Lo riferisce Universe Today.",
   "more": [
    "Le fosse lunari sono aperture nel suolo della Luna, spesso legate a antichi tunnel di lava. La fossa di Marius si trova in una regione vulcanica del lato visibile. Le cavità sotterranee interessano gli scienziati perché potrebbero proteggere gli astronauti da radiazioni, micrometeoriti e forti escursioni termiche."
   ],
